export interface Frontmatter {
  title: string;
  date: Date | null;
  tags: string[];
  draft: boolean;
  layout?: string;
  [key: string]: unknown;
}

export interface Post {
  /** URL slug relative to site root, e.g. "posts/hello-world" */
  slug: string;
  /** Source file path */
  sourcePath: string;
  frontmatter: Frontmatter;
  /** Rendered HTML body */
  html: string;
  /** Raw markdown body */
  markdown: string;
  /** Plain-text excerpt for RSS */
  excerpt: string;
  url: string;
}

export interface SiteConfig {
  sourceDir: string;
  templateDir: string;
  outDir: string;
  baseUrl: string;
  title: string;
  includeDrafts: boolean;
}

export interface BuildResult {
  posts: Post[];
  tagIndex: Map<string, Post[]>;
  pagesWritten: string[];
}

import matter from "gray-matter";
import { Marked } from "marked";
import hljs from "highlight.js";
import type { Frontmatter } from "./types.js";

/** Normalize raw frontmatter values into a typed Frontmatter object. */
export function normalizeFrontmatter(raw: Record<string, unknown>, fallbackTitle: string): Frontmatter {
  const title = typeof raw.title === "string" && raw.title.trim() !== "" ? raw.title : fallbackTitle;

  let date: Date | null = null;
  if (raw.date instanceof Date) {
    date = raw.date;
  } else if (typeof raw.date === "string" && raw.date.trim() !== "") {
    const parsed = new Date(raw.date);
    if (!Number.isNaN(parsed.getTime())) date = parsed;
  }

  let tags: string[] = [];
  if (Array.isArray(raw.tags)) {
    tags = raw.tags.map(String).map((t) => t.trim()).filter(Boolean);
  } else if (typeof raw.tags === "string") {
    tags = raw.tags.split(",").map((t) => t.trim()).filter(Boolean);
  }

  const draft = raw.draft === true || raw.draft === "true";

  return { ...raw, title, date, tags, draft, layout: typeof raw.layout === "string" ? raw.layout : undefined };
}

export interface ParsedDocument {
  frontmatter: Frontmatter;
  body: string;
}

/** Parse a markdown document with optional YAML frontmatter. */
export function parseDocument(source: string, fallbackTitle = "Untitled"): ParsedDocument {
  const { data, content } = matter(source);
  return { frontmatter: normalizeFrontmatter(data, fallbackTitle), body: content };
}

function escapeHtml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

const marked = new Marked({
  gfm: true,
  renderer: {
    code(code: string, infostring: string | undefined): string {
      const lang = (infostring ?? "").trim().split(/\s+/)[0] ?? "";
      if (lang && hljs.getLanguage(lang)) {
        const { value } = hljs.highlight(code, { language: lang });
        return `<pre><code class="hljs language-${lang}">${value}</code></pre>\n`;
      }
      return `<pre><code class="hljs">${escapeHtml(code)}</code></pre>\n`;
    },
  },
});

/** Render markdown to HTML with syntax-highlighted code blocks. */
export function renderMarkdown(markdown: string): string {
  return marked.parse(markdown) as string;
}

/** Plain-text excerpt of the first `maxLength` characters. */
export function makeExcerpt(markdown: string, maxLength = 280): string {
  const text = markdown
    .replace(/```[\s\S]*?```/g, "")
    .replace(/`([^`]*)`/g, "$1")
    .replace(/!\[[^\]]*\]\([^)]*\)/g, "")
    .replace(/\[([^\]]*)\]\([^)]*\)/g, "$1")
    .replace(/[#>*_~-]/g, "")
    .replace(/\s+/g, " ")
    .trim();
  return text.length > maxLength ? `${text.slice(0, maxLength - 1)}…` : text;
}

import Handlebars from "handlebars";
import fs from "node:fs";
import path from "node:path";

/**
 * Template engine wrapping Handlebars.
 *
 * Directory convention:
 *   templates/
 *     index.hbs, post.hbs, tag.hbs   -- page templates
 *     layouts/*.hbs                  -- layouts; page output is injected as {{{body}}}
 *     partials/*.hbs                 -- registered as partials by filename
 */
export class TemplateEngine {
  private hbs = Handlebars.create();
  private pages = new Map<string, Handlebars.TemplateDelegate>();
  private layouts = new Map<string, Handlebars.TemplateDelegate>();

  constructor(private templateDir: string) {
    this.registerHelpers();
    this.load();
  }

  /** Reload all templates from disk (used by the dev server on changes). */
  reload(): void {
    this.hbs = Handlebars.create();
    this.pages.clear();
    this.layouts.clear();
    this.registerHelpers();
    this.load();
  }

  private registerHelpers(): void {
    this.hbs.registerHelper("formatDate", (date: unknown, fmt?: unknown) => {
      if (!(date instanceof Date)) return "";
      if (fmt === "iso") return date.toISOString();
      return date.toISOString().slice(0, 10);
    });
    this.hbs.registerHelper("eq", (a: unknown, b: unknown) => a === b);
    this.hbs.registerHelper("join", (arr: unknown, sep: unknown) =>
      Array.isArray(arr) ? arr.join(typeof sep === "string" ? sep : ", ") : ""
    );
  }

  private load(): void {
    if (!fs.existsSync(this.templateDir)) {
      throw new Error(`Template directory not found: ${this.templateDir}`);
    }
    for (const entry of fs.readdirSync(this.templateDir, { withFileTypes: true })) {
      const full = path.join(this.templateDir, entry.name);
      if (entry.isFile() && entry.name.endsWith(".hbs")) {
        this.pages.set(path.basename(entry.name, ".hbs"), this.hbs.compile(fs.readFileSync(full, "utf8")));
      } else if (entry.isDirectory() && entry.name === "partials") {
        for (const f of fs.readdirSync(full).filter((f) => f.endsWith(".hbs"))) {
          this.hbs.registerPartial(path.basename(f, ".hbs"), fs.readFileSync(path.join(full, f), "utf8"));
        }
      } else if (entry.isDirectory() && entry.name === "layouts") {
        for (const f of fs.readdirSync(full).filter((f) => f.endsWith(".hbs"))) {
          this.layouts.set(path.basename(f, ".hbs"), this.hbs.compile(fs.readFileSync(path.join(full, f), "utf8")));
        }
      }
    }
  }

  hasPage(name: string): boolean {
    return this.pages.has(name);
  }

  /**
   * Render a page template, then wrap it in a layout (if one is given and exists).
   * The rendered page is exposed to the layout as {{{body}}}.
   */
  render(page: string, context: Record<string, unknown>, layout?: string): string {
    const tpl = this.pages.get(page);
    if (!tpl) throw new Error(`Template not found: ${page}.hbs in ${this.templateDir}`);
    const body = tpl(context);
    const layoutName = layout ?? "default";
    const layoutTpl = this.layouts.get(layoutName);
    if (layout && !layoutTpl) throw new Error(`Layout not found: layouts/${layout}.hbs`);
    if (!layoutTpl) return body;
    return layoutTpl({ ...context, body });
  }
}

import type { Post, SiteConfig } from "./types.js";

function esc(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

/** Generate an RSS 2.0 feed for the given (already sorted, newest first) posts. */
export function generateRss(posts: Post[], site: SiteConfig, limit = 20): string {
  const base = site.baseUrl.replace(/\/$/, "");
  const items = posts.slice(0, limit).map((post) => {
    const url = `${base}${post.url}`;
    const pubDate = post.frontmatter.date ? `\n      <pubDate>${post.frontmatter.date.toUTCString()}</pubDate>` : "";
    const categories = post.frontmatter.tags.map((t) => `\n      <category>${esc(t)}</category>`).join("");
    return `    <item>
      <title>${esc(post.frontmatter.title)}</title>
      <link>${esc(url)}</link>
      <guid>${esc(url)}</guid>
      <description>${esc(post.excerpt)}</description>${pubDate}${categories}
    </item>`;
  });

  return `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0">
  <channel>
    <title>${esc(site.title)}</title>
    <link>${esc(base || "/")}</link>
    <description>${esc(site.title)}</description>
    <lastBuildDate>${new Date().toUTCString()}</lastBuildDate>
${items.join("\n")}
  </channel>
</rss>
`;
}

import fs from "node:fs";
import path from "node:path";
import { parseDocument, renderMarkdown, makeExcerpt } from "./content.js";
import { TemplateEngine } from "./templates.js";
import { generateRss } from "./rss.js";
import type { BuildResult, Post, SiteConfig } from "./types.js";

function walk(dir: string): string[] {
  if (!fs.existsSync(dir)) return [];
  const out: string[] = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) out.push(...walk(full));
    else out.push(full);
  }
  return out;
}

export function slugify(s: string): string {
  return s
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

/** Load and parse all posts from the source directory. */
export function loadPosts(site: SiteConfig): Post[] {
  const files = walk(site.sourceDir).filter((f) => f.endsWith(".md"));
  const posts: Post[] = [];
  for (const file of files) {
    const rel = path.relative(site.sourceDir, file);
    const fallbackTitle = path.basename(file, ".md");
    const { frontmatter, body } = parseDocument(fs.readFileSync(file, "utf8"), fallbackTitle);
    if (frontmatter.draft && !site.includeDrafts) continue;
    const slug = rel.replace(/\.md$/, "").split(path.sep).map(slugify).join("/");
    posts.push({
      slug,
      sourcePath: file,
      frontmatter,
      markdown: body,
      html: renderMarkdown(body),
      excerpt: makeExcerpt(body),
      url: `/${slug}/`,
    });
  }
  posts.sort((a, b) => (b.frontmatter.date?.getTime() ?? 0) - (a.frontmatter.date?.getTime() ?? 0));
  return posts;
}

/** Group posts by tag. */
export function buildTagIndex(posts: Post[]): Map<string, Post[]> {
  const index = new Map<string, Post[]>();
  for (const post of posts) {
    for (const tag of post.frontmatter.tags) {
      const key = slugify(tag);
      const list = index.get(key) ?? [];
      list.push(post);
      index.set(key, list);
    }
  }
  return index;
}

function writeFile(outDir: string, relPath: string, content: string, written: string[]): void {
  const full = path.join(outDir, relPath);
  fs.mkdirSync(path.dirname(full), { recursive: true });
  fs.writeFileSync(full, content);
  written.push(relPath);
}

/** Copy non-markdown files from source to output verbatim (static assets). */
function copyAssets(site: SiteConfig, written: string[]): void {
  for (const file of walk(site.sourceDir).filter((f) => !f.endsWith(".md"))) {
    const rel = path.relative(site.sourceDir, file);
    const dest = path.join(site.outDir, rel);
    fs.mkdirSync(path.dirname(dest), { recursive: true });
    fs.copyFileSync(file, dest);
    written.push(rel);
  }
}

/** Full site build: posts, index, tag pages, RSS, assets. */
export function buildSite(site: SiteConfig): BuildResult {
  const engine = new TemplateEngine(site.templateDir);
  const posts = loadPosts(site);
  const tagIndex = buildTagIndex(posts);
  const written: string[] = [];
  const siteCtx = { title: site.title, baseUrl: site.baseUrl };

  fs.mkdirSync(site.outDir, { recursive: true });

  for (const post of posts) {
    const html = engine.render(
      "post",
      { ...post.frontmatter, post, content: post.html, site: siteCtx },
      post.frontmatter.layout ?? (engine.hasPage("post") ? undefined : undefined)
    );
    writeFile(site.outDir, path.join(post.slug, "index.html"), html, written);
  }

  const tags = [...tagIndex.keys()].sort().map((tag) => ({ tag, count: tagIndex.get(tag)!.length, url: `/tags/${tag}/` }));

  if (engine.hasPage("index")) {
    const html = engine.render("index", { posts, tags, site: siteCtx, title: site.title });
    writeFile(site.outDir, "index.html", html, written);
  }

  if (engine.hasPage("tag")) {
    for (const [tag, tagPosts] of tagIndex) {
      const html = engine.render("tag", { tag, posts: tagPosts, site: siteCtx, title: `Tag: ${tag}` });
      writeFile(site.outDir, path.join("tags", tag, "index.html"), html, written);
    }
  }

  writeFile(site.outDir, "rss.xml", generateRss(posts, site), written);
  copyAssets(site, written);

  return { posts, tagIndex, pagesWritten: written };
}

