import fs from "node:fs";
import os from "node:os";
import path from "node:path";

export function makeTmpDir(): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), "ssg-test-"));
}

/** Write a tree of files: { "a/b.md": "content", ... } */
export function writeTree(root: string, files: Record<string, string>): void {
  for (const [rel, content] of Object.entries(files)) {
    const full = path.join(root, rel);
    fs.mkdirSync(path.dirname(full), { recursive: true });
    fs.writeFileSync(full, content);
  }
}

export const BASIC_TEMPLATES: Record<string, string> = {
  "layouts/default.hbs": "<!DOCTYPE html><html><head><title>{{title}}</title></head><body>{{{body}}}</body></html>",
  "partials/header.hbs": "<header>{{site.title}}</header>",
  "post.hbs": "{{> header}}<article><h1>{{title}}</h1>{{{content}}}</article>",
  "index.hbs":
    "{{> header}}<ul>{{#each posts}}<li><a href=\"{{url}}\">{{frontmatter.title}}</a></li>{{/each}}</ul>" +
    "<div class=\"tags\">{{#each tags}}<a href=\"{{url}}\">{{tag}} ({{count}})</a>{{/each}}</div>",
  "tag.hbs": "<h1>Tag: {{tag}}</h1><ul>{{#each posts}}<li>{{frontmatter.title}}</li>{{/each}}</ul>",
};

import { describe, it, expect } from "vitest";
import { parseDocument, renderMarkdown, makeExcerpt, normalizeFrontmatter } from "../src/content.js";

describe("frontmatter parsing", () => {
  it("parses title, date, tags, draft", () => {
    const doc = parseDocument(
      `---
title: Hello World
date: 2024-03-15
tags: [alpha, beta]
draft: true
---
Body text.`
    );
    expect(doc.frontmatter.title).toBe("Hello World");
    expect(doc.frontmatter.date).toBeInstanceOf(Date);
    expect(doc.frontmatter.date!.toISOString().slice(0, 10)).toBe("2024-03-15");
    expect(doc.frontmatter.tags).toEqual(["alpha", "beta"]);
    expect(doc.frontmatter.draft).toBe(true);
    expect(doc.body.trim()).toBe("Body text.");
  });

  it("handles missing frontmatter with fallback title", () => {
    const doc = parseDocument("Just markdown.", "my-file");
    expect(doc.frontmatter.title).toBe("my-file");
    expect(doc.frontmatter.date).toBeNull();
    expect(doc.frontmatter.tags).toEqual([]);
    expect(doc.frontmatter.draft).toBe(false);
    expect(doc.body).toBe("Just markdown.");
  });

  it("accepts comma-separated tag strings", () => {
    const fm = normalizeFrontmatter({ tags: "a, b , c" }, "x");
    expect(fm.tags).toEqual(["a", "b", "c"]);
  });

  it("accepts YAML list tags with mixed types and trims", () => {
    const fm = normalizeFrontmatter({ tags: [" a ", 1, ""] }, "x");
    expect(fm.tags).toEqual(["a", "1"]);
  });

  it("parses string dates and rejects invalid ones", () => {
    expect(normalizeFrontmatter({ date: "2020-01-02" }, "x").date!.getUTCFullYear()).toBe(2020);
    expect(normalizeFrontmatter({ date: "not a date" }, "x").date).toBeNull();
  });

  it("treats draft: 'true' string as draft, everything else as not", () => {
    expect(normalizeFrontmatter({ draft: "true" }, "x").draft).toBe(true);
    expect(normalizeFrontmatter({ draft: false }, "x").draft).toBe(false);
    expect(normalizeFrontmatter({}, "x").draft).toBe(false);
  });

  it("preserves extra frontmatter fields", () => {
    const fm = normalizeFrontmatter({ author: "Ada", layout: "special" }, "x");
    expect(fm.author).toBe("Ada");
    expect(fm.layout).toBe("special");
  });
});

describe("markdown rendering", () => {
  it("renders basic markdown", () => {
    const html = renderMarkdown("# Heading\n\nSome **bold** text.");
    expect(html).toContain("<h1");
    expect(html).toContain("<strong>bold</strong>");
  });

  it("syntax-highlights known languages", () => {
    const html = renderMarkdown("```js\nconst x = 1;\n```");
    expect(html).toContain('class="hljs language-js"');
    expect(html).toContain("hljs-keyword");
  });

  it("escapes code for unknown languages without highlighting", () => {
    const html = renderMarkdown("```nosuchlang\n<b>&raw</b>\n```");
    expect(html).toContain("&lt;b&gt;&amp;raw&lt;/b&gt;");
    expect(html).not.toContain("language-nosuchlang");
  });

  it("escapes code with no language tag", () => {
    const html = renderMarkdown("```\na < b\n```");
    expect(html).toContain("a &lt; b");
  });
});

describe("makeExcerpt", () => {
  it("strips markdown syntax and code blocks", () => {
    const md = "# Title\n\n```js\nconst hidden = true;\n```\n\nSome *emphasis* and [a link](http://x.test).";
    const excerpt = makeExcerpt(md);
    expect(excerpt).not.toContain("hidden");
    expect(excerpt).toContain("a link");
    expect(excerpt).not.toContain("[");
    expect(excerpt).not.toContain("*");
  });

  it("truncates long text with ellipsis", () => {
    const excerpt = makeExcerpt("word ".repeat(200), 50);
    expect(excerpt.length).toBeLessThanOrEqual(50);
    expect(excerpt.endsWith("…")).toBe(true);
  });
});

import { describe, it, expect, beforeEach } from "vitest";
import fs from "node:fs";
import path from "node:path";
import { TemplateEngine } from "../src/templates.js";
import { makeTmpDir, writeTree, BASIC_TEMPLATES } from "./helpers.js";

describe("TemplateEngine", () => {
  let dir: string;

  beforeEach(() => {
    dir = makeTmpDir();
    writeTree(dir, BASIC_TEMPLATES);
  });

  it("renders a page template with context", () => {
    const engine = new TemplateEngine(dir);
    const html = engine.render("post", { title: "Hi", content: "<p>Body</p>", site: { title: "Site" } });
    expect(html).toContain("<h1>Hi</h1>");
    expect(html).toContain("<p>Body</p>");
  });

  it("renders partials", () => {
    const engine = new TemplateEngine(dir);
    const html = engine.render("post", { title: "T", content: "", site: { title: "My Blog" } });
    expect(html).toContain("<header>My Blog</header>");
  });

  it("wraps output in the default layout, exposing {{{body}}}", () => {
    const engine = new TemplateEngine(dir);
    const html = engine.render("post", { title: "Page Title", content: "<p>x</p>", site: {} });
    expect(html).toContain("<!DOCTYPE html>");
    expect(html).toContain("<title>Page Title</title>");
    expect(html).toContain("<article>");
  });

  it("uses a named layout when given", () => {
    writeTree(dir, { "layouts/bare.hbs": "<main>{{{body}}}</main>" });
    const engine = new TemplateEngine(dir);
    const html = engine.render("post", { title: "T", content: "", site: {} }, "bare");
    expect(html).toContain("<main>");
    expect(html).not.toContain("<!DOCTYPE html>");
  });

  it("throws for a missing named layout", () => {
    const engine = new TemplateEngine(dir);
    expect(() => engine.render("post", {}, "nope")).toThrow(/Layout not found/);
  });

  it("renders without a layout if no default layout exists", () => {
    fs.rmSync(path.join(dir, "layouts"), { recursive: true });
    const engine = new TemplateEngine(dir);
    const html = engine.render("post", { title: "T", content: "<p>x</p>", site: {} });
    expect(html).not.toContain("<!DOCTYPE html>");
    expect(html).toContain("<h1>T</h1>");
  });

  it("throws for an unknown page template", () => {
    const engine = new TemplateEngine(dir);
    expect(() => engine.render("missing", {})).toThrow(/Template not found/);
  });

  it("throws for a missing template directory", () => {
    expect(() => new TemplateEngine(path.join(dir, "nope"))).toThrow(/Template directory not found/);
  });

  it("provides formatDate, eq, and join helpers", () => {
    writeTree(dir, {
      "helpers.hbs": "{{formatDate date}}|{{formatDate date 'iso'}}|{{#if (eq a 'x')}}yes{{/if}}|{{join list '+'}}",
    });
    const engine = new TemplateEngine(dir);
    const html = engine.render("helpers", { date: new Date("2024-03-15T12:00:00Z"), a: "x", list: ["a", "b"] });
    expect(html).toBe("2024-03-15|2024-03-15T12:00:00.000Z|yes|a+b");
  });

  it("reload() picks up template changes", () => {
    const engine = new TemplateEngine(dir);
    writeTree(dir, { "post.hbs": "CHANGED {{title}}" });
    expect(engine.render("post", { title: "T", content: "", site: {} })).not.toContain("CHANGED");
    engine.reload();
    expect(engine.render("post", { title: "T", content: "", site: {} })).toContain("CHANGED T");
  });
});

import { describe, it, expect, beforeEach } from "vitest";
import fs from "node:fs";
import path from "node:path";
import { buildSite, buildTagIndex, loadPosts, slugify } from "../src/build.js";
import type { SiteConfig } from "../src/types.js";
import { makeTmpDir, writeTree, BASIC_TEMPLATES } from "./helpers.js";

function makeSite(overrides: Partial<SiteConfig> = {}): SiteConfig {
  const root = makeTmpDir();
  const site: SiteConfig = {
    sourceDir: path.join(root, "content"),
    templateDir: path.join(root, "templates"),
    outDir: path.join(root, "out"),
    baseUrl: "https://example.com",
    title: "Test Site",
    includeDrafts: false,
    ...overrides,
  };
  writeTree(site.templateDir, BASIC_TEMPLATES);
  writeTree(site.sourceDir, {
    "hello.md": `---\ntitle: Hello\ndate: 2024-01-02\ntags: [news, misc]\n---\n# Hello\n\nFirst post.`,
    "posts/second.md": `---\ntitle: Second\ndate: 2024-02-03\ntags: [news]\n---\nSecond post with code:\n\n\`\`\`js\nconst x = 1;\n\`\`\`\n`,
    "secret.md": `---\ntitle: Secret\ndraft: true\n---\nHidden.`,
    "style.css": "body { color: red; }",
  });
  return site;
}

describe("slugify", () => {
  it("lowercases and dashes non-alphanumerics", () => {
    expect(slugify("Hello World!")).toBe("hello-world");
    expect(slugify("  --A_B--  ")).toBe("a-b");
  });
});

describe("loadPosts", () => {
  it("skips drafts by default and sorts newest first", () => {
    const site = makeSite();
    const posts = loadPosts(site);
    expect(posts.map((p) => p.frontmatter.title)).toEqual(["Second", "Hello"]);
  });

  it("includes drafts when includeDrafts is set", () => {
    const site = makeSite({ includeDrafts: true });
    const posts = loadPosts({ ...site, includeDrafts: true });
    expect(posts.map((p) => p.frontmatter.title)).toContain("Secret");
  });

  it("derives nested slugs and URLs from file paths", () => {
    const site = makeSite();
    const second = loadPosts(site).find((p) => p.frontmatter.title === "Second")!;
    expect(second.slug).toBe("posts/second");
    expect(second.url).toBe("/posts/second/");
  });
});

describe("buildTagIndex", () => {
  it("groups posts by slugified tag", () => {
    const site = makeSite();
    const index = buildTagIndex(loadPosts(site));
    expect([...index.keys()].sort()).toEqual(["misc", "news"]);
    expect(index.get("news")!.length).toBe(2);
    expect(index.get("misc")!.length).toBe(1);
  });
});

describe("buildSite", () => {
  let site: SiteConfig;
  beforeEach(() => {
    site = makeSite();
  });

  const read = (rel: string) => fs.readFileSync(path.join(site.outDir, rel), "utf8");

  it("writes post pages wrapped in the layout", () => {
    buildSite(site);
    const html = read("hello/index.html");
    expect(html).toContain("<!DOCTYPE html>");
    expect(html).toContain("<title>Hello</title>");
    expect(html).toContain("First post.");
    expect(html).toContain("<header>Test Site</header>");
  });

  it("applies syntax highlighting in built pages", () => {
    buildSite(site);
    expect(read("posts/second/index.html")).toContain("hljs-keyword");
  });

  it("writes an index page listing all posts", () => {
    buildSite(site);
    const html = read("index.html");
    expect(html).toContain('href="/hello/"');
    expect(html).toContain('href="/posts/second/"');
    expect(html).not.toContain("Secret");
  });

  it("writes tag index pages", () => {
    buildSite(site);
    const news = read("tags/news/index.html");
    expect(news).toContain("Tag: news");
    expect(news).toContain("Hello");
    expect(news).toContain("Second");
    const misc = read("tags/misc/index.html");
    expect(misc).not.toContain("Second");
  });

  it("links tag pages from the index", () => {
    buildSite(site);
    expect(read("index.html")).toContain('href="/tags/news/"');
    expect(read("index.html")).toContain("news (2)");
  });

  it("generates a valid RSS feed with absolute links, dates, categories", () => {
    buildSite(site);
    const rss = read("rss.xml");
    expect(rss).toContain('<rss version="2.0">');
    expect(rss).toContain("<title>Test Site</title>");
    expect(rss).toContain("<link>https://example.com/hello/</link>");
    expect(rss).toContain("<category>news</category>");
    expect(rss).toMatch(/<pubDate>[A-Z][a-z]{2}, \d{2} [A-Z][a-z]{2} \d{4}/);
    expect(rss).not.toContain("Secret");
  });

  it("escapes XML entities in RSS", () => {
    writeTree(site.sourceDir, {
      "amp.md": `---\ntitle: "Fish & <Chips>"\ndate: 2024-05-05\n---\nx`,
    });
    buildSite(site);
    expect(read("rss.xml")).toContain("<title>Fish &amp; &lt;Chips&gt;</title>");
  });

  it("copies static assets verbatim", () => {
    buildSite(site);
    expect(read("style.css")).toBe("body { color: red; }");
  });

  it("excludes drafts from output but includes them with includeDrafts", () => {
    buildSite(site);
    expect(fs.existsSync(path.join(site.outDir, "secret/index.html"))).toBe(false);
    buildSite({ ...site, includeDrafts: true });
    expect(fs.existsSync(path.join(site.outDir, "secret/index.html"))).toBe(true);
  });

  it("honors a per-post layout override", () => {
    writeTree(site.templateDir, { "layouts/bare.hbs": "<main>{{{body}}}</main>" });
    writeTree(site.sourceDir, {
      "bare-post.md": `---\ntitle: Bare\nlayout: bare\ndate: 2024-06-06\n---\nx`,
    });
    buildSite(site);
    const html = read("bare-post/index.html");
    expect(html).toContain("<main>");
    expect(html).not.toContain("<!DOCTYPE html>");
  });

  it("reports written pages in the result", () => {
    const result = buildSite(site);
    expect(result.posts.length).toBe(2);
    expect(result.pagesWritten).toContain("index.html");
    expect(result.pagesWritten).toContain("rss.xml");
    expect(result.pagesWritten.some((p) => p.includes("tags"))).toBe(true);
  });
});

import { describe, it, expect } from "vitest";
import path from "node:path";
import { parseArgs, toSiteConfig, DEFAULTS } from "../src/cli.js";

describe("parseArgs", () => {
  it("defaults to help with no args", () => {
    expect(parseArgs([]).command).toBe("help");
    expect(parseArgs(["--help"]).command).toBe("help");
    expect(parseArgs(["-h"]).command).toBe("help");
  });

  it("parses the build command with defaults", () => {
    const opts = parseArgs(["build"]);
    expect(opts.command).toBe("build");
    expect(opts.source).toBe(DEFAULTS.source);
    expect(opts.templates).toBe(DEFAULTS.templates);
    expect(opts.out).toBe(DEFAULTS.out);
    expect(opts.drafts).toBe(false);
    expect(opts.port).toBe(DEFAULTS.port);
  });

  it("parses long flags", () => {
    const opts = parseArgs([
      "build",
      "--source", "src-md",
      "--templates", "tpl",
      "--out", "public",
      "--base-url", "https://blog.test",
      "--title", "Blog",
      "--drafts",
    ]);
    expect(opts.source).toBe("src-md");
    expect(opts.templates).toBe("tpl");
    expect(opts.out).toBe("public");
    expect(opts.baseUrl).toBe("https://blog.test");
    expect(opts.title).toBe("Blog");
    expect(opts.drafts).toBe(true);
  });

  it("parses short aliases", () => {
    const opts = parseArgs(["serve", "-s", "a", "-t", "b", "-o", "c", "-p", "8080"]);
    expect(opts.command).toBe("serve");
    expect(opts.source).toBe("a");
    expect(opts.templates).toBe("b");
    expect(opts.out).toBe("c");
    expect(opts.port).toBe(8080);
  });

  it("rejects unknown commands and flags", () => {
    expect(() => parseArgs(["frobnicate"])).toThrow(/Unknown command/);
    expect(() => parseArgs(["build", "--wat"])).toThrow(/Unknown flag/);
  });

  it("rejects missing flag values", () => {
    expect(() => parseArgs(["build", "--source"])).toThrow(/Missing value/);
    expect(() => parseArgs(["build", "--source", "--drafts"])).toThrow(/Missing value/);
  });

  it("validates port numbers", () => {
    expect(() => parseArgs(["serve", "--port", "abc"])).toThrow(/Invalid port/);
    expect(() => parseArgs(["serve", "--port", "70000"])).toThrow(/Invalid port/);
    expect(parseArgs(["serve", "--port", "0"]).port).toBe(0);
  });
});

describe("toSiteConfig", () => {
  it("resolves directories against cwd and maps options", () => {
    const opts = parseArgs(["build", "-s", "md", "-o", "out", "--drafts", "--title", "T", "--base-url", "https://x.test"]);
    const site = toSiteConfig(opts, "/work");
    expect(site.sourceDir).toBe(path.resolve("/work", "md"));
    expect(site.outDir).toBe(path.resolve("/work", "out"));
    expect(site.templateDir).toBe(path.resolve("/work", "templates"));
    expect(site.includeDrafts).toBe(true);
    expect(site.title).toBe("T");
    expect(site.baseUrl).toBe("https://x.test");
  });
});

import { describe, it, expect, afterEach } from "vitest";
import path from "node:path";
import { injectReloadScript, resolveRequestPath, serve, RELOAD_SCRIPT, type DevServer } from "../src/server.js";
import type { SiteConfig } from "../src/types.js";
import { makeTmpDir, writeTree, BASIC_TEMPLATES } from "./helpers.js";

describe("injectReloadScript", () => {
  it("injects before </body> when present", () => {
    const out = injectReloadScript("<html><body><p>x</p></body></html>");
    expect(out).toContain(RELOAD_SCRIPT);
    expect(out.indexOf(RELOAD_SCRIPT)).toBeLessThan(out.indexOf("</body>"));
  });

  it("appends when no </body> exists", () => {
    const out = injectReloadScript("<p>fragment</p>");
    expect(out.endsWith(RELOAD_SCRIPT)).toBe(true);
  });
});

describe("resolveRequestPath", () => {
  it("serves directory index.html and blocks traversal", () => {
    const root = makeTmpDir();
    writeTree(root, { "index.html": "home", "a/index.html": "a", "a/x.css": "css" });
    expect(resolveRequestPath(root, "/")).toBe(path.join(root, "index.html"));
    expect(resolveRequestPath(root, "/a/")).toBe(path.join(root, "a", "index.html"));
    expect(resolveRequestPath(root, "/a/x.css")).toBe(path.join(root, "a", "x.css"));
    expect(resolveRequestPath(root, "/missing")).toBeNull();
    expect(resolveRequestPath(root, "/../../etc/passwd")).toBeNull();
    expect(resolveRequestPath(root, "/%2e%2e/%2e%2e/etc/passwd")).toBeNull();
  });
});

describe("dev server (integration)", () => {
  let server: DevServer | undefined;

  afterEach(async () => {
    await server?.close();
    server = undefined;
  });

  it("builds, serves HTML with the reload script injected, and 404s unknown paths", async () => {
    const root = makeTmpDir();
    const site: SiteConfig = {
      sourceDir: path.join(root, "content"),
      templateDir: path.join(root, "templates"),
      outDir: path.join(root, "out"),
      baseUrl: "http://localhost",
      title: "Dev",
      includeDrafts: false,
    };
    writeTree(site.templateDir, BASIC_TEMPLATES);
    writeTree(site.sourceDir, { "hi.md": `---\ntitle: Hi\ndate: 2024-01-01\n---\nHello dev` });

    server = await serve(site, 0);
    const base = `http://localhost:${server.port}`;

    const home = await fetch(`${base}/`);
    expect(home.status).toBe(200);
    expect(home.headers.get("content-type")).toContain("text/html");
    const html = await home.text();
    expect(html).toContain("Hello dev");
    expect(html).toContain("__livereload");

    const rss = await fetch(`${base}/rss.xml`);
    expect(rss.status).toBe(200);
    expect(await rss.text()).not.toContain("__livereload");

    const missing = await fetch(`${base}/nope`);
    expect(missing.status).toBe(404);
  });
});

